export function searchStories(query, topN = 3) {
  if (!query) return STORIES.slice(0, topN);
  const q = query.toLowerCase();
  const terms = q.split(/[\s,.;:!?]+/).filter(Boolean);
  const scored = STORIES.map(s => {
    let score = 0;
    const haystack = [
      s.title, s.character, s.summary, s.situationTags.join(" "), s.keywords.join(" "), s.strategy.name, s.strategy.steps.join(" ")
    ].join(" ").toLowerCase();
    for (const t of terms) {
      if (s.situationTags.some(tag => tag.includes(t) || t.includes(tag))) score += 5;
      if (haystack.includes(t)) score += 2;
      if (s.keywords.some(k => k.toLowerCase() === t)) score += 4;
    }
    // bonus for exact tag match
    if (s.situationTags.some(tag => q.includes(tag))) score += 10;
    return { story: s, score };
  });
  scored.sort((a,b) => b.score - a.score);
  const filtered = scored.filter(x => x.score > 0).slice(0, topN).map(x => x.story);
  // fallback: if no match, return most universal stories
  if (filtered.length === 0) return [STORIES[0], STORIES[1], STORIES[4]];
  return filtered;
}
